changeSet.sql:
ALTER TABLE modeling_model_spec_import_apply_attempt DROP CONSTRAINT ck_model_spec_import_apply_attempt_status; ALTER TABLE modeling_model_spec_import_apply_result DROP CONSTRAINT ck_model_spec_import_apply_result_status;
UPDATE modeling_model_spec_import_apply_result SET status = 'SKIPPED' WHERE status = 'REPLAYED';
UPDATE modeling_model_spec_import_apply_result SET issues_json = '[]'::jsonb WHERE issues_json IS NULL OR jsonb_typeof(issues_json) <> 'array';
UPDATE modeling_model_spec_import_apply_result result SET issues_json = jsonb_build_array( jsonb_build_object( 'code', 'MODEL_IMPORT_LEGACY_FAILURE', 'severity', 'ERROR', 'stage', 'APPLY', 'category', 'INTERNAL', 'retryable', result.status = 'FAILED', 'fieldPath', '$.items', 'modelUniqueId', result.dbt_unique_id, 'message', 'A legacy apply failure requires operator review', 'recoveryAction', CASE WHEN result.status = 'FAILED' THEN 'RETRY' ELSE 'CONTACT_ADMIN' END, 'correlationId', 'legacy-' || md5(result.id::text || ':0') ) ) WHERE result.status IN ('FAILED', 'BLOCKED') AND jsonb_array_length(result.issues_json) = 0;
WITH enriched_issues AS ( SELECT result.id, COALESCE( jsonb_agg( issue.value || jsonb_build_object( 'code', to_jsonb( CASE WHEN btrim(COALESCE(issue.value ->> 'code', '')) = '' THEN 'MODEL_IMPORT_LEGACY_FAILURE' ELSE issue.value ->> 'code' END ), 'severity', to_jsonb( CASE WHEN issue.value ->> 'severity' IN ('ERROR', 'WARNING', 'INFO') THEN issue.value ->> 'severity' ELSE 'ERROR' END ), 'stage', to_jsonb( CASE WHEN issue.value ->> 'stage' IN ( 'INSPECT', 'MAPPING', 'PREVIEW', 'APPLY', 'RETRY', 'UNDO' ) THEN issue.value ->> 'stage' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_APPLY_INTERRUPTED' THEN 'RETRY' ELSE 'APPLY' END ), 'category', to_jsonb( CASE WHEN issue.value ->> 'category' IN ( 'VALIDATION', 'SECURITY', 'DEPENDENCY', 'CONFLICT', 'PERMISSION', 'STALE', 'PERSISTENCE', 'INTERNAL' ) THEN issue.value ->> 'category' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_APPLY_INTERRUPTED' THEN 'PERSISTENCE' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_DEPENDENCY_FAILED' THEN 'DEPENDENCY' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_IDEMPOTENCY_CONFLICT' THEN 'CONFLICT' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_APPLY_CANDIDATE_NOT_SELECTED' THEN 'VALIDATION' ELSE 'INTERNAL' END ), 'retryable', CASE WHEN jsonb_typeof(issue.value -> 'retryable') = 'boolean' THEN issue.value -> 'retryable' ELSE to_jsonb(result.status = 'FAILED') END, 'modelUniqueId', to_jsonb( COALESCE(NULLIF(btrim(issue.value ->> 'modelUniqueId'), ''), result.dbt_unique_id) ), 'message', to_jsonb( COALESCE( NULLIF(btrim(issue.value ->> 'message'), ''), 'A legacy apply failure requires operator review' ) ), 'recoveryAction', to_jsonb( CASE WHEN issue.value ->> 'recoveryAction' IN ( 'REUPLOAD', 'COMPLETE_MAPPING', 'INCLUDE_DEPENDENCY', 'RESOLVE_CONFLICT', 'REAUTHORIZE', 'REFRESH_PREVIEW', 'RETRY', 'OPEN_MODEL', 'CONTACT_ADMIN', 'NONE' ) THEN issue.value ->> 'recoveryAction' WHEN issue.value ->> 'code' = 'MODEL_IMPORT_APPLY_CANDIDATE_NOT_SELECTED' THEN 'REFRESH_PREVIEW' WHEN result.status = 'FAILED' THEN 'RETRY' ELSE 'CONTACT_ADMIN' END ), 'correlationId', to_jsonb( COALESCE( NULLIF(btrim(issue.value ->> 'correlationId'), ''), 'legacy-' || md5(result.id::text || ':' || issue.ordinality::text) ) ) ) || CASE WHEN COALESCE(issue.value ->> 'category', '') = 'DEPENDENCY' OR issue.value ->> 'code' = 'MODEL_IMPORT_DEPENDENCY_FAILED' THEN jsonb_build_object( 'dependencyUniqueId', COALESCE( NULLIF(btrim(issue.value ->> 'dependencyUniqueId'), ''), 'legacy-unresolved-' || md5(result.id::text || ':' || issue.ordinality::text) ) ) ELSE '{}'::jsonb END ORDER BY issue.ordinality ) FILTER (WHERE issue.value IS NOT NULL), '[]'::jsonb ) AS issues_json FROM modeling_model_spec_import_apply_result result LEFT JOIN LATERAL jsonb_array_elements(COALESCE(result.issues_json, '[]'::jsonb)) WITH ORDINALITY AS issue(value, ordinality) ON TRUE GROUP BY result.id, result.status ) UPDATE modeling_model_spec_import_apply_result result SET issues_json = enriched_issues.issues_json FROM enriched_issues WHERE result.id = enriched_issues.id;
WITH facts AS ( SELECT attempt.id, jsonb_array_length(attempt.selected_closure_json) AS selected, count(result.id)::int AS terminal, count(*) FILTER (WHERE result.status = 'CREATED')::int AS created, count(*) FILTER (WHERE result.status = 'UPDATED')::int AS updated, count(*) FILTER (WHERE result.status = 'SKIPPED')::int AS skipped, count(*) FILTER (WHERE result.status = 'FAILED')::int AS failed, count(*) FILTER (WHERE result.status = 'BLOCKED')::int AS blocked FROM modeling_model_spec_import_apply_attempt attempt LEFT JOIN modeling_model_spec_import_apply_result result ON result.attempt_id = attempt.id GROUP BY attempt.id ), canonical AS ( SELECT id, selected, selected - terminal AS pending, created + updated AS succeeded, created, updated, skipped, failed, blocked, CASE WHEN selected - terminal > 0 THEN 'RUNNING' WHEN failed + blocked = 0 AND created + updated + skipped = selected THEN 'SUCCESS' WHEN created + updated + skipped > 0 AND failed + blocked > 0 THEN 'PARTIAL' WHEN created + updated + skipped = 0 AND failed > 0 THEN 'FAILED' WHEN created + updated + skipped = 0 AND failed = 0 AND blocked > 0 THEN 'BLOCKED' END AS status FROM facts ) UPDATE modeling_model_spec_import_apply_attempt attempt SET status = canonical.status, summary_json = jsonb_build_object( 'selected', canonical.selected, 'pending', canonical.pending, 'succeeded', canonical.succeeded, 'created', canonical.created, 'updated', canonical.updated, 'skipped', canonical.skipped, 'failed', canonical.failed, 'blocked', canonical.blocked ) FROM canonical WHERE attempt.id = canonical.id;
ALTER TABLE modeling_model_spec_import_apply_attempt ADD CONSTRAINT ck_model_spec_import_apply_attempt_status CHECK (status IN ('RUNNING', 'SUCCESS', 'PARTIAL', 'FAILED', 'BLOCKED')), ADD CONSTRAINT ck_model_spec_import_apply_summary_canonical CHECK ( jsonb_typeof(summary_json) = 'object' AND jsonb_typeof(summary_json -> 'selected') = 'number' AND jsonb_typeof(summary_json -> 'pending') = 'number' AND jsonb_typeof(summary_json -> 'succeeded') = 'number' AND jsonb_typeof(summary_json -> 'created') = 'number' AND jsonb_typeof(summary_json -> 'updated') = 'number' AND jsonb_typeof(summary_json -> 'skipped') = 'number' AND jsonb_typeof(summary_json -> 'failed') = 'number' AND jsonb_typeof(summary_json -> 'blocked') = 'number' AND (summary_json ->> 'selected')::int >= 0 AND (summary_json ->> 'pending')::int >= 0 AND (summary_json ->> 'succeeded')::int >= 0 AND (summary_json ->> 'created')::int >= 0 AND (summary_json ->> 'updated')::int >= 0 AND (summary_json ->> 'skipped')::int >= 0 AND (summary_json ->> 'failed')::int >= 0 AND (summary_json ->> 'blocked')::int >= 0 AND (summary_json ->> 'succeeded')::int = (summary_json ->> 'created')::int + (summary_json ->> 'updated')::int AND (summary_json ->> 'selected')::int = (summary_json ->> 'pending')::int + (summary_json ->> 'created')::int + (summary_json ->> 'updated')::int + (summary_json ->> 'skipped')::int + (summary_json ->> 'failed')::int + (summary_json ->> 'blocked')::int AND ( (status = 'RUNNING' AND (summary_json ->> 'pending')::int > 0) OR ( status = 'SUCCESS' AND (summary_json ->> 'pending')::int = 0 AND (summary_json ->> 'failed')::int + (summary_json ->> 'blocked')::int = 0 AND (summary_json ->> 'succeeded')::int + (summary_json ->> 'skipped')::int = (summary_json ->> 'selected')::int ) OR ( status = 'PARTIAL' AND (summary_json ->> 'pending')::int = 0 AND (summary_json ->> 'succeeded')::int + (summary_json ->> 'skipped')::int > 0 AND (summary_json ->> 'failed')::int + (summary_json ->> 'blocked')::int > 0 ) OR ( status = 'FAILED' AND (summary_json ->> 'pending')::int = 0 AND (summary_json ->> 'succeeded')::int + (summary_json ->> 'skipped')::int = 0 AND (summary_json ->> 'failed')::int > 0 ) OR ( status = 'BLOCKED' AND (summary_json ->> 'pending')::int = 0 AND (summary_json ->> 'succeeded')::int + (summary_json ->> 'skipped')::int = 0 AND (summary_json ->> 'failed')::int = 0 AND (summary_json ->> 'blocked')::int > 0 ) ) );
ALTER TABLE modeling_model_spec_import_apply_result ADD CONSTRAINT ck_model_spec_import_apply_result_status CHECK (status IN ('CREATED', 'UPDATED', 'SKIPPED', 'FAILED', 'BLOCKED')), ADD CONSTRAINT ck_model_spec_import_apply_issue_contract CHECK ( jsonb_typeof(issues_json) = 'array' AND ( status NOT IN ('FAILED', 'BLOCKED') OR jsonb_array_length(issues_json) > 0 ) AND NOT jsonb_path_exists( issues_json, '$[*] ? ( !exists(@.code) || @.code == "" || !exists(@.severity) || !(@.severity == "ERROR" || @.severity == "WARNING" || @.severity == "INFO") || !exists(@.stage) || !( @.stage == "INSPECT" || @.stage == "MAPPING" || @.stage == "PREVIEW" || @.stage == "APPLY" || @.stage == "RETRY" || @.stage == "UNDO" ) || !exists(@.category) || !( @.category == "VALIDATION" || @.category == "SECURITY" || @.category == "DEPENDENCY" || @.category == "CONFLICT" || @.category == "PERMISSION" || @.category == "STALE" || @.category == "PERSISTENCE" || @.category == "INTERNAL" ) || !exists(@.retryable) || !(@.retryable == true || @.retryable == false) || !exists(@.modelUniqueId) || @.modelUniqueId == "" || !exists(@.message) || @.message == "" || !exists(@.recoveryAction) || !( @.recoveryAction == "REUPLOAD" || @.recoveryAction == "COMPLETE_MAPPING" || @.recoveryAction == "INCLUDE_DEPENDENCY" || @.recoveryAction == "RESOLVE_CONFLICT" || @.recoveryAction == "REAUTHORIZE" || @.recoveryAction == "REFRESH_PREVIEW" || @.recoveryAction == "RETRY" || @.recoveryAction == "OPEN_MODEL" || @.recoveryAction == "CONTACT_ADMIN" || @.recoveryAction == "NONE" ) || !exists(@.correlationId) || @.correlationId == "" || @.correlationId == null || (@.category == "DEPENDENCY" && ( !exists(@.dependencyUniqueId) || @.dependencyUniqueId == "" )) )' ) );

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_SPEC_IMPORT_STATUS_CANONICAL_FORWARD_ONLY: Recovery requires a new forward changeset';
END $$;
